    private static readonly List<PrimitiveObjectToy> ParentToys = [];
    private static readonly List<ushort> Scp1162Pickups = [];

    public override void OnServerRoundStarted()
    {
        SpawnScp1162();
        base.OnServerRoundStarted();
    }

    public override void OnPlayerInteractedToy(PlayerInteractedToyEventArgs ev)
    {
        try
        {
            LogManager.Debug($"Player {ev.Player.Nickname} interacted with {ev.Interactable.GameObject.name}");
            if (ev.Interactable.GameObject.name != "SCP1162")
            {
                LogManager.Debug($"Interact ignored: not SCP1162 (name={ev.Interactable.GameObject.name})");
                return;
            }

            if (Scp1162.Singleton.Config == null)
            {
                LogManager.Debug("Interact aborted: Config is null.");
                return;
            }

            if ((ev.Player.Role is RoleTypeId.Scp3114 && !Scp1162.Singleton.Config.CanScp3114Use) ||
                (ev.Player is { IsSCP: true, Role: not RoleTypeId.Scp3114 } && !Scp1162.Singleton.Config.CanScpsUse))
            {
                LogManager.Debug($"Player {ev.Player.Nickname} role {ev.Player.Role} not allowed to use SCP-1162.");
                return;
            }

            var percentDisappearing = Scp1162.Singleton.Config.PercentDisappearing;
            LogManager.Debug($"PercentDisappearing={percentDisappearing}");

            if (ev.Player.CurrentItem != null)
            {
                LogManager.Debug($"Player {ev.Player.Nickname} has current item {ev.Player.CurrentItem.Type}");
                if (ev.Player.CurrentItem.Type == ItemType.Snowball)
                {
                    LogManager.Debug("Interaction blocked: current item is Snowball.");
                    ev.Player.SendHint(Scp1162.Singleton.Config.CantUseSnowball);
                    return;
                }

                var roll = Random.Range(0f, 100f);
                LogManager.Debug($"Disappearing roll={roll}");
                if (percentDisappearing == 0 || roll > percentDisappearing)
                {
                    LogManager.Debug("Giving item to player.");
                    GiveItem(ev.Player);
                }
                else
                {
                    LogManager.Debug("Item will disappear on interaction.");
                    if (ev.Player.CurrentItem != null) ev.Player.RemoveItem(ev.Player.CurrentItem);
                    ev.Player.SendHint(Scp1162.Singleton.Config.LostItemHint);
                }
            }
            else
            {
                LogManager.Debug($"Player {ev.Player.Nickname} has no item; applying damage path.");
                if (Scp1162.Singleton.Config.HealthMinus == 0)
                {
                    LogManager.Debug("HealthMinus is 0; skipping damage.");
                    return;
                }

                ev.Player.Damage(Scp1162.Singleton.Config.HealthMinus, "SCP-1162");
                ev.Player.EnableEffect<Burned>(3, 5);
                ev.Player.SendHint(Scp1162.Singleton.Config.DamageHint);
            }
        }
        catch (Exception e)
        {
            LogManager.Error($"Error while interacting with SCP-1162: {e}");
        }

        base.OnPlayerInteractedToy(ev);
    }

    public override void OnPlayerPickingUpItem(PlayerPickingUpItemEventArgs ev)
    {
        if (Scp1162Pickups.Contains(ev.Pickup.Serial))
        {
            ev.IsAllowed = false;
            LogManager.Debug(
                $"Player {ev.Player.Nickname} tried to pick up SCP-1162 pickup (serial={ev.Pickup.Serial}).");

            if (Scp1162.Singleton.Config == null)
            {
                LogManager.Debug("Pickup handling aborted: Config is null.");
                return;
            }

            if (ev.Player.Role is RoleTypeId.Scp3114 && !Scp1162.Singleton.Config.CanScp3114Use)
            {
                LogManager.Debug($"Pickup blocked: player role {ev.Player.Role} not allowed.");
                return;
            }

            var percentDisappearing = Scp1162.Singleton.Config.PercentDisappearing;
            LogManager.Debug($"Pickup PercentDisappearing={percentDisappearing}");

            if (ev.Player.CurrentItem != null)
            {
                LogManager.Debug(
                    $"Player {ev.Player.Nickname} has current item {ev.Player.CurrentItem.Type} while picking up.");
                if (ev.Player.CurrentItem.Type == ItemType.Snowball)
                {
                    LogManager.Debug("Pickup blocked: current item is Snowball.");
                    ev.Player.SendHint(Scp1162.Singleton.Config.CantUseSnowball);
                    return;
                }

                var roll = Random.Range(0f, 100f);
                LogManager.Debug($"Pickup disappearing roll={roll}");
                if (percentDisappearing == 0 || roll > percentDisappearing)
                {
                    LogManager.Debug("Giving item to player from pickup.");
                    GiveItem(ev.Player);
                }
                else
                {
                    LogManager.Debug("Pickup will cause current item to be lost.");
                    if (ev.Player.CurrentItem != null) ev.Player.RemoveItem(ev.Player.CurrentItem);
                    ev.Player.SendHint(Scp1162.Singleton.Config.LostItemHint);
                }
            }
            else
            {
                LogManager.Debug($"Player {ev.Player.Nickname} has no item on pickup; applying damage path.");
                if (Scp1162.Singleton.Config.HealthMinus == 0)
                {
                    LogManager.Debug("Pickup damage skipped: HealthMinus is 0.");
                    return;
                }

                ev.Player.Damage(Scp1162.Singleton.Config.HealthMinus, "SCP-1162");
                ev.Player.EnableEffect<Burned>(3, 5);
                ev.Player.SendHint(Scp1162.Singleton.Config.DamageHint);
            }
        }

        base.OnPlayerPickingUpItem(ev);
    }

    public override void OnServerWaitingForPlayers()
    {
        VersionManager.CheckForUpdates();
        base.OnServerWaitingForPlayers();
    }

    public static void SpawnScp1162()
    {
        try
        {
            if (Scp1162.Singleton.Config == null)
            {
                LogManager.Error("[SpawnScp1162 ]SCP-1162 configuration is null.");
                return;
            }

            LogManager.Debug($"SpawnScp1162: UsePickup={Scp1162.Singleton.Config.UsePickup}");

            if (Scp1162.Singleton.Config.UsePickup)
                foreach (var customRoomLocation in Scp1162.Singleton.Config.CustomPickupLocations)
                {
                    var chanceRoll = Random.Range(0f, 100f);
                    LogManager.Debug(
                        $"Checking pickup location {customRoomLocation.RoomName} with chance {customRoomLocation.Chance}, roll={chanceRoll}");
                    if (chanceRoll > customRoomLocation.Chance)
                        continue;

                    var room = Room.List.FirstOrDefault(room => room.Name == customRoomLocation.RoomName);
                    if (room == null)
                    {
                        LogManager.Debug($"Pickup spawn aborted: room '{customRoomLocation.RoomName}' not found.");
                        return;
                    }

                    var mainOffset = room.Transform.TransformPoint(customRoomLocation.Offset);
                    var rotation = room.Transform.rotation * Quaternion.Euler(customRoomLocation.Rotation);

                    var parentToy = PrimitiveObjectToy.Create();
                    parentToy.Type = PrimitiveType.Cube;
                    parentToy.Flags = PrimitiveFlags.None;
                    parentToy.GameObject.name = $"SCP1162-{room.Name}-{Guid.NewGuid()}";
                    parentToy.Position = mainOffset;
                    parentToy.Rotation = rotation;
                    LogManager.Debug(
                        $"Created parentToy for pickup at {mainOffset} (name={parentToy.GameObject.name})");

                    var scp1162Pick = Pickup.Create(ItemType.SCP500, mainOffset);
                    if (scp1162Pick == null || scp1162Pick.Rigidbody == null)
                    {
                        LogManager.Error("Failed to create SCP-1162 pickup.");
                        return;
                    }

                    scp1162Pick.GameObject.name = $"SCP1162Pickup-{room.Name}-{Guid.NewGuid()}";
                    scp1162Pick.Rotation = rotation;
                    scp1162Pick.Rigidbody.useGravity = false;
                    scp1162Pick.Rigidbody.detectCollisions = false;
                    scp1162Pick.Transform.localScale = new Vector3(10, 10, 10);
                    scp1162Pick.Spawn();
                    Scp1162Pickups.Add(scp1162Pick.Serial);
                    LogManager.Debug($"Spawned pickup with serial={scp1162Pick.Serial} at {mainOffset}");
                }
            else
                foreach (var customRoomLocation in Scp1162.Singleton.Config.CustomTextRoomLocations)
                {
                    var chanceRoll = Random.Range(0f, 100f);
                    LogManager.Debug(
                        $"Checking text location {customRoomLocation.RoomName} with chance {customRoomLocation.Chance}, roll={chanceRoll}");
                    if (chanceRoll > customRoomLocation.Chance)
                        continue;

                    var room = Room.List.FirstOrDefault(room => room.Name == customRoomLocation.RoomName);
                    if (room == null)
                    {
                        LogManager.Debug($"Text spawn aborted: room '{customRoomLocation.RoomName}' not found.");
                        return;
                    }

                    var mainOffset = room.Transform.TransformPoint(customRoomLocation.Offset);
                    var rotation = room.Transform.rotation * Quaternion.Euler(customRoomLocation.Rotation);

                    var parentToy = PrimitiveObjectToy.Create();
                    parentToy.Type = PrimitiveType.Cube;
                    parentToy.Flags = PrimitiveFlags.None;
                    parentToy.GameObject.name = $"SCP1162-{room.Name}-{Guid.NewGuid()}";
                    parentToy.Position = mainOffset;
                    parentToy.Rotation = rotation;

                    foreach (var toyData in TextToys)
                    {
                        var textToy = TextToy.Create(parentToy.Transform);
                        textToy.GameObject.name = "Scp1162Text";
                        textToy.TextFormat = toyData.Text;
                        textToy.Position = toyData.Offset;
                        textToy.Scale = new Vector3(0.514f, 0.514f, 0.514f);
                        textToy.Rotation = new Quaternion(0, 0, 1, 0);
                    }

                    var toy = InteractableToy.Create(parentToy.Transform);
                    toy.GameObject.name = InteractableToyData.Name;
                    toy.Position = InteractableToyData.Offset;
                    toy.Scale = InteractableToyData.Scale;
                    LogManager.Debug($"Created SCP-1162 at {toy.GameObject.transform.position}");
                    ParentToys.Add(parentToy);
                }
        }
        catch (Exception e)
        {
            LogManager.Error($"Error while spawning SCP-1162: {e}");
        }
    }

    public static void DestroyScp1162()
    {
        try
        {
            LogManager.Debug($"DestroyScp1162: ParentToys={ParentToys.Count}, Pickups={Scp1162Pickups.Count}");
            foreach (var primitiveObjectToy in ParentToys)
                primitiveObjectToy.Destroy();
            ParentToys.Clear();

            foreach (var pickupSerial in Scp1162Pickups)
                if (Pickup.TryGet(pickupSerial, out var pickup))
                    pickup.Destroy();
            Scp1162Pickups.Clear();
            LogManager.Debug("DestroyScp1162: cleared ParentToys and Scp1162Pickups");
        }
        catch (Exception e)
        {
            LogManager.Error($"Error while destroying SCP-1162: {e}");
        }
    }

    private static void GiveItem(Player player)
    {
        try
        {
            var items = Scp1162.Singleton.Config.ItemsToGive;

            LogManager.Debug($"GiveItem: giving to player {player.Nickname}");
            player.SendHint(Scp1162.Singleton.Config.InteractionHint, 20);
            if (player.CurrentItem != null)
            {
                LogManager.Debug(
                    $"GiveItem: removing existing item {player.CurrentItem.Type} from player {player.Nickname}");
                player.RemoveItem(player.CurrentItem);
            }

            player.CurrentItem = null;

            Timing.CallDelayed(0.1f, () =>
            {
                var isFullOfCandy = player.Items.Any(candyBag => candyBag is Scp330Item { Candies.Count: >= 6 });
                LogManager.Debug($"GiveItem: isFullOfCandy={isFullOfCandy}");
                if (isFullOfCandy || Scp1162.Singleton.Config.PercentCandy == 0 ||
                    Random.Range(0f, 100f) > Scp1162.Singleton.Config.PercentCandy)
                {
                    var randomItem = items.RandomItem();
                    int num = Mathf.Abs(InventoryLimits.GetCategoryLimit(randomItem.GetTemplate().Category, player.ReferenceHub));

                    while (player.Items.Count(item => item.Category == randomItem.GetTemplate().Category) >= num)
                    {
                        randomItem = items.RandomItem();
                        num = Mathf.Abs(InventoryLimits.GetCategoryLimit(randomItem.GetTemplate().Category, player.ReferenceHub));
                    }
                    LogManager.Debug($"GiveItem: selected item {randomItem}");
                    var item = player.AddItem(randomItem);
                    if (item is FirearmItem firearmItem && !Scp1162.Singleton.Config.GiveWeaponWithAmmo)
                    {
                        LogManager.Debug("GiveItem: stripping ammo from firearm item.");
                        firearmItem.StoredAmmo = 0;
                        firearmItem.ChamberedAmmo = 0;
                    }

                    player.CurrentItem = item;
                    LogManager.Debug($"GiveItem: player {player.Nickname} received item {item.Type}");
                    return;
                }

                var randomCandy = Scp1162.Singleton.Config.CandiesToGive.RandomItem();
                LogManager.Debug($"GiveItem: giving candy {randomCandy} to player {player.Nickname}");
                player.GiveCandy(randomCandy, ItemAddReason.Undefined);
            });
        }
        catch (Exception e)
        {
            LogManager.Error($"Error while giving item from SCP-1162: {e}");
        }
    }

    private class CustomTextToyData
    {
        public string Text { get; set; }
        public Vector3 Offset { get; set; }
    }

    private class CustomInteractableToyData
    {
        public string Name { get; set; }
        public Vector3 Offset { get; set; }
        public Vector3 Scale { get; set; }
    }
